-- Set-operation column count and type errors name their operation and point
-- at the right input's column; DEFAULT outside an inserted or assigned value
-- is rejected where it is written, even when no row is read.
CREATE TABLE t215 (a int, b text);
SELECT 1 UNION SELECT 'x'::text;
SELECT 1, 2 UNION SELECT 3;
SELECT a FROM t215 UNION SELECT b FROM t215;
SELECT a FROM t215 INTERSECT SELECT a, b FROM t215;
SELECT 1 UNION SELECT 2 UNION SELECT now();
VALUES (1), ('a'::text);
VALUES (1, 2), (3);
SELECT DEFAULT;
SELECT 1 + DEFAULT;
UPDATE t215 SET a = DEFAULT + 1;
INSERT INTO t215 VALUES (DEFAULT + 1, 'x');
SELECT * FROM t215 WHERE a = DEFAULT;
INSERT INTO t215 SELECT DEFAULT, 'x';
VALUES (DEFAULT);
INSERT INTO t215 VALUES ((DEFAULT), 'x');
SELECT 1 EXCEPT SELECT true;
(SELECT 1) UNION ALL (SELECT 'a'::text, 1);
SELECT ARRAY[1] UNION SELECT 2;
CREATE TABLE u215 (a int PRIMARY KEY, b text DEFAULT 'd');
INSERT INTO u215 VALUES (1, DEFAULT), (2, 'x');
INSERT INTO u215 VALUES (1, 'y') ON CONFLICT (a) DO UPDATE SET b = DEFAULT;
UPDATE u215 SET (a, b) = (a, DEFAULT) WHERE a = 2;
UPDATE u215 SET (a, b) = ROW(a, DEFAULT) WHERE a = 2;
MERGE INTO u215 USING (VALUES (3)) v(x) ON u215.a = v.x WHEN NOT MATCHED THEN INSERT VALUES (v.x, DEFAULT);
MERGE INTO u215 USING (VALUES (3)) v(x) ON u215.a = v.x WHEN MATCHED THEN UPDATE SET b = DEFAULT;
SELECT * FROM u215 ORDER BY a;
CREATE FUNCTION f215() RETURNS void LANGUAGE plpgsql AS $$ BEGIN INSERT INTO u215 VALUES (9, DEFAULT); UPDATE u215 SET b = DEFAULT WHERE a = 9; END $$;
SELECT f215();
PREPARE p215 AS UPDATE u215 SET b = DEFAULT WHERE a = $1;
EXECUTE p215(1);
SELECT * FROM u215 ORDER BY a;
UPDATE u215 SET b = (DEFAULT);
UPDATE u215 SET (a, b) = (SELECT DEFAULT, 'x');
INSERT INTO u215 VALUES (5, 'q') ON CONFLICT (a) DO UPDATE SET b = coalesce(DEFAULT, 'x');
INSERT INTO u215 VALUES (DEFAULT, 'x') UNION SELECT 1, 'y';
DROP FUNCTION f215(); DEALLOCATE p215; DROP TABLE t215, u215;
